# Weights for hybrid search on unstructured content.
SEMANTIC_WEIGHT = 0.7
BM25_WEIGHT = 0.3

# Number of top sentences to return from hybrid search.
TOP_K_SENTENCES = 3

MAX_RECALL_ATTEMPTS = 3

_HINT_DESC_CHARS = 120

