class SmartRetriever:
    """
    Backs the `recall_from_memory` tool exposed to the execution agent.

    The single entry point is `retrieve()`, which runs a dspy.RLM over the
    full observation store (every archived observation as an id->content map).
    For long unstructured documents the RLM can call the internal
    `hybrid_search` tool (0.7 semantic + 0.3 BM25) or `grep` to pull the most
    relevant passages from a specific stored document.

    Cost attribution: each retrieve() call is wrapped in dspy.track_usage(),
    dspy's native usage tracker. One SmartRetriever is created per task, so
    its `run_id` groups every recall in that task; see fastworkflow.rlm_cost.
    """

    def __init__(self):
        self._embedder = None      # lazy-loaded to avoid startup cost
        self._lm = None            # lazy-loaded
        self.run_id = new_run_id()
        register_task(self.run_id)
        # One SmartRetriever per task -> set the task identity for deep components
        # (param extraction) that have no run_id in scope, and start the per-task
        # wall clock here so it spans the whole task.
        from fastworkflow import task_metrics
        task_metrics.set_current_run_id(self.run_id)
        task_metrics.start_task_wall_clock(self.run_id)

    # ------------------------------------------------------------------
    # LM (built once, reused)
    # ------------------------------------------------------------------

    def _get_lm(self):
        if self._lm is None:
            from fastworkflow.utils.dspy_utils import get_lm
            try:
                self._lm = get_lm("LLM_AGENT", "LITELLM_API_KEY_AGENT",tool_choice="auto" ,cache=False)
            except Exception:
                # Fall back to the execution agent's model config.
                self._lm = get_lm("LLM_AGENT", "LITELLM_API_KEY_AGENT" ,tool_choice="auto",cache=False)
        return self._lm

    def _compact_failure_hint(
        self,
        observation_store,
        visible_keys: list[str],
        query: str,
        last_error: Exception | None,
    ) -> str:
        """Compact replacement for the old full-store dump.

        When the RLM exhausts its retries (or hits a non-retryable error), the
        recall tool returns this hint instead of the entire serialised content.
        It tells the agent which archived ids exist and what each holds, in a
        bounded number of bytes regardless of how much is in memory — so the
        trajectory does not bloat.
        """
        err_label = (
            f"{type(last_error).__name__}: {last_error}"
            if last_error is not None
            else "unknown error"
        )
        lines = [
            "[recall_from_memory] Could not extract a focused answer for "
            f"query: {query!r} (last error: {err_label}).",
            "",
            "Archived ids currently in memory",
        ]
        for k in visible_keys:
            desc = (observation_store.description(k) or "").strip()
            if desc:
                desc_short = desc[:_HINT_DESC_CHARS].rstrip()
                if len(desc) > _HINT_DESC_CHARS:
                    desc_short += "…"
                lines.append(f"  - {k}  —  {desc_short}")
            else:
                lines.append(f"  - {k}")
        return "\n".join(lines)


    def retrieve(self, observation_store, query: str, session_id: str | None = None) -> str:
        """Return the answer to `query` extracted from the full observation store."""
        all_keys = observation_store.all_keys()
        visible_keys = [k for k in all_keys if k != "_domain_policy"]
        
        keys_index_key = f"__keys_index__{len(visible_keys)}"
        content = {
            keys_index_key: visible_keys,
            "__content_dict__": {
                k: observation_store.get(k) or "" for k in visible_keys
            },
        }

        rlm_log(f"\n{'@'*10}")
        rlm_log(f"[SMART RETRIEVER] recall request")
        rlm_log(f"  QUERY       : {query}")
        rlm_log(f"  CONTENT KEYS: {list(content.keys())}")
        rlm_log(f"{'@'*10}")

        if not content:
            return ("[recall_from_memory] Memory is empty — nothing has been "
                    "archived yet. There is nothing to recall.")

        llm = None
        usage = None
        start = time.time()
        extracted: str | None = None
        last_error: Exception | None = None
        try:
            import dspy
            import logging
            # dspy logger is set to ERROR globally; bump rlm to INFO so verbose=True is visible.
            logging.getLogger("dspy.predict.rlm").setLevel(logging.INFO)

            llm = self._get_lm()

            hybrid_search_tool = self._make_hybrid_search_tool(observation_store)
            grep_tool = self._make_grep_tool(observation_store)

            # Serialize content so the model sees both ids and values.
            content_str = json.dumps(content, indent=2,default=str)
            print(f"Content going to RLM: {content_str}")
            class Retrieval(dspy.Signature):
                """You are a READ-ONLY EXTRACTOR. You do not perform actions.

                Your ONLY job is to locate and return information that already
                exists inside `content` dictionary and answers `query`. Search all keys in the JSON map exhaustively, before returning an answer.
                This may be a specific factual value (an id, amount, status, date), a list of
                items, a summary of details about an entity, an explanation,
                or any other information present in `content` dictionary. `content` dictionary is a
                JSON map of key -> tool-response from previous tool calls. The
                keys are human-readable LABELS describing what each response
                contains — they are NOT functions and cannot be called. All
                data you need is already in `content`. Nothing else exists.

                A DATABASE SCHEMA is included at the END of these instructions
                (the "DATABASE SCHEMA" section). It describes the database these
                tool-responses come from (the USER, ORDER and PRODUCT entities
                and their fields). It is REFERENCE MATERIAL ONLY — never the
                source of an answer. You MUST consult it on EVERY query to work
                out WHICH entity and WHICH field holds the value `query` is
                asking about, before you look at `content`.

                The FIRST entry of `content` is always
                "__keys_index__<N>" (where <N> is the number of archived keys,
                e.g. "__keys_index__5") — a JSON array listing every archived
                key currently in memory. <N> tells you EXACTLY how many keys
                exist, you MUST look at ALL <N> of them and account 
                for every one before you decide which key(s) hold the answer. 
                Do not stop early or decide after scanning only a few.
                You MUST read "__keys_index__<N>" before deciding what is or is not present.
                It is the authoritative list of what exists; do not judge presence/absence from what you
                happen to "see" in the rest of the prompt.

                The SECOND entry of `content` is always "__content_dict__" — a
                nested JSON object mapping each archived key -> its
                tool-response. All the actual data you extract answers from
                lives inside "__content_dict__". Both "__keys_index__<N>" and
                "__content_dict__" itself are metadata wrappers — never the
                target of the answer.

                Workflow you MUST follow:
                  1. Read the DATABASE SCHEMA section (at the end of these
                     instructions) FIRST to understand the database — which
                     entity and which field the value asked for in `query`
                     lives under.
                  2. Pick the key whose entity matches `query` — compare the
                     entity referenced in `query` against each key in
                     "__keys_index__<N>" and choose the matching one.
                  3. Read content["__content_dict__"][id] (json.loads it again
                     if it is a JSON string) and extract the answer from the
                     field the DATABASE SCHEMA told you to look in.

                Additonal tools available for you:
                  1. Call `hybrid_search(doc_key, query)` — when document is long 
                     unstructured text. `doc_key` must be an id that exists in `content` dictionary.
                  2. Call `grep(doc_key, pattern)` — when you need exact substring
                     or regex pattern lookup inside a stored document. `doc_key`
                     must be an id that exists in `content`.

                You MUST NOT:
                  - Treat any id/key in `content` dictionary as a callable function. The ids
                    are descriptive labels, not tools.
                  - Call any function whose name resembles a domain action or
                    command. NO such functions exist in your environment; attempting to call one will fail.
                  - Invent helper functions or pretend a tool exists.


                The `query` is always a QUESTION ABOUT THE DATA, even when
                phrased as an action statement. 

                Rules you MUST follow:
                - Extract whatever information in `content` dictionary answers `query`,
                  matching the granularity of the answer to what `query` asks.
                - Do NOT fabricate any value that is not present in `content` dictionary.
                - If `content` dictionary does not contain the answer, say so explicitly
                  rather than guessing or calling external functions.
                - Search all keys in the JSON map exhaustively, before returning an answer.
                - The DATABASE SCHEMA's "Attributes under 'options' for each
                  product" reference lists, per product, the option attribute
                  names — use them to look up specifications when needed.

                STRICT OUTPUT CONTRACT:
                - Output ONLY raw executable Python code.
                - Output MUST be directly executable.
                - Do NOT output tool-calling schema.
                - NEVER output: {"name": "...", "arguments": ...}
                """

                content: str = dspy.InputField(
                    desc="JSON map. First entry '__keys_index__<N>' (<N> = number "
                         "of archived keys) is the full list of archived keys — "
                         "read it first to know what exists. Second entry "
                         "'__content_dict__' is a nested object mapping id -> "
                         "tool-response; the actual data lives there. Keys are "
                         "descriptive labels, not callable functions. Search all "
                         "keys exhaustively."
                )
                query: str = dspy.InputField(
                    desc="The information the execution agent needs right now."
                )
                answer: str = dspy.OutputField(
                    desc="The information from `content` dictionary that answers `query`, at "
                         "whatever granularity the query requires. Must be extracted "
                         "from `content` dictionary. Never hallucinate or invent values."
                )

            Retrieval = Retrieval.with_instructions(
                Retrieval.instructions
                + "\n\n===== DATABASE SCHEMA (consult on EVERY query) =====\n"
                + DATABASE_SCHEMA
            )
            
            rlm = dspy.RLM(Retrieval, tools=[hybrid_search_tool, grep_tool],verbose=True, sub_lm=llm)
            
            for attempt in range(1, MAX_RECALL_ATTEMPTS + 1):
                try:
                    with dspy.context(lm=llm), dspy.track_usage() as usage:
                        result = rlm(content=content_str, query=query)
                    extracted = result.answer
                    rlm_log(
                        f"  [RLM] attempt {attempt}/{MAX_RECALL_ATTEMPTS} succeeded: "
                        f"{extracted}"
                    )
                    return extracted
                except Exception as e:
                    last_error = e
                    rlm_log(
                        f"  [RLM] attempt {attempt}/{MAX_RECALL_ATTEMPTS} failed "
                        f"({type(e).__name__}: {e})"
                    )
                    if attempt == MAX_RECALL_ATTEMPTS:
                        rlm_log(
                            f"  [RLM] exhausted {MAX_RECALL_ATTEMPTS} attempts; "
                            "falling back to compact hint"
                        )

            
            return self._compact_failure_hint(
                observation_store, visible_keys, query, last_error
            )
        finally:
            # Attribute cost to RLM from dspy's native usage tracker.
            duration = time.time() - start
            usage_totals = {}
            try:
                if usage is not None:
                    usage_totals = usage.get_total_tokens()
            except Exception as e:
                rlm_log(f"[RLM COST] could not read usage totals: {e}")
            try:
                record_rlm_call(self.run_id, session_id, query, usage_totals, duration)
            except Exception as e:
                rlm_log(f"[RLM COST] cost attribution failed: {e}")

    # ------------------------------------------------------------------
    # Internal tools exposed to the RLM
    # ------------------------------------------------------------------

    def _make_hybrid_search_tool(self, observation_store):
        """Closure-based tool so the RLM can hybrid-search within a stored document."""
        retriever = self

        def hybrid_search(doc_key: str, query: str) -> str:
            """Run hybrid search (0.7 semantic + 0.3 BM25) over the unstructured
            content stored under `doc_key` and return the top-3 most relevant
            sentences for `query`. Use this when content is unstructured text that is too noisy to read in full.
             `doc_key` must be one of the keys present in the `content` input."""
            content = observation_store.get(doc_key)
            if content is None:
                return f"[hybrid_search] no content found for doc_key={doc_key}"
            return retriever._hybrid_search(content, query)

        return hybrid_search

    def _make_grep_tool(self, observation_store):
        """Closure-based tool so the RLM can grep for exact patterns in a stored document."""

        def grep(doc_key: str, pattern: str) -> str:
            """Return all lines from the content stored under `doc_key` that match
            the regex `pattern` (case-insensitive). Use this for exact substring
            or pattern lookup (ids, emails, keywords) inside a stored document.
            `doc_key` must be one of the ids present in the `content` input.
            Returns up to 50 matching lines, or a not-found message."""
            content = observation_store.get(doc_key)
            if content is None:
                return f"[grep] no content found for doc_key={doc_key}"
            text = content if isinstance(content, str) else json.dumps(content, default=str)
            try:
                regex = re.compile(pattern, re.IGNORECASE)
            except re.error as e:
                return f"[grep] invalid regex pattern: {e}"
            matches = [line for line in text.splitlines() if regex.search(line)]
            if not matches:
                return f"[grep] no matches for pattern={pattern!r} in doc_key={doc_key}"
            return "\n".join(matches[:50])

        return grep

    # ------------------------------------------------------------------
    # Hybrid search implementation (semantic + BM25)
    # ------------------------------------------------------------------

    def _hybrid_search(self, content: str, query: str) -> str:
        sentences = self._split_sentences(content)
        if len(sentences) <= 1:
            return content

        bm25_scores = self._bm25_scores(sentences, query)
        semantic_scores = self._semantic_scores(sentences, query)

        combined = [
            SEMANTIC_WEIGHT * semantic_scores[i] + BM25_WEIGHT * bm25_scores[i]
            for i in range(len(sentences))
        ]

        top_indices = sorted(
            sorted(range(len(combined)), key=lambda i: combined[i], reverse=True)[:TOP_K_SENTENCES]
        )
        return " ".join(sentences[i] for i in top_indices)

    def _split_sentences(self, content: str) -> list[str]:
        parts = re.split(r'(?<=[.!?])\s+|\n+', content.strip())
        return [p.strip() for p in parts if p.strip()]

    def _bm25_scores(self, sentences: list[str], query: str) -> list[float]:
        from rank_bm25 import BM25Okapi
        tokenized = [s.lower().split() for s in sentences]
        bm25 = BM25Okapi(tokenized)
        scores = bm25.get_scores(query.lower().split())
        max_score = max(scores) if max(scores) > 0 else 1.0
        return [s / max_score for s in scores]  # normalize to [0,1]

    def _semantic_scores(self, sentences: list[str], query: str) -> list[float]:
        import torch
        embedder = self._get_embedder()
        embeddings = embedder.encode([query] + sentences, convert_to_tensor=True)
        query_emb = embeddings[0]
        sent_embs = embeddings[1:]
        scores = torch.nn.functional.cosine_similarity(
            query_emb.unsqueeze(0), sent_embs
        ).tolist()
        return [(s + 1) / 2 for s in scores]  # shift cosine to [0,1]

    def _get_embedder(self):
        if self._embedder is None:
            from sentence_transformers import SentenceTransformer
            self._embedder = SentenceTransformer("all-MiniLM-L6-v2")
        return self._embedder
